      // Parse 'catch' clauses
      elements.append(self.parseCatchClause())
    }

    return RawDoExprSyntax(
      unexpectedBeforeDoKeyword,
      doKeyword: doKeyword,
      body( body ,
      catchClauses: RawCatchClauseListSyntax(elements: elements, arena: self.arena),
